long long W[MAXN];
long long ans[MAXN];

int N, Q;
long long K;

void get_bounds(int u) {
    L_bound[u] = u;
    R_bound[u] = u;
    if (left_child[u]) {
        get_bounds(left_child[u]);
        L_bound[u] = L_bound[left_child[u]];
    }
    if (right_child[u]) {
        get_bounds(right_child[u]);
        R_bound[u] = R_bound[right_child[u]];
    }
}

void solve_tree(int u) {
    if (!u) return;
    solve_tree(left_child[u]);
    solve_tree(right_child[u]);

    int Lu = L_bound[u];
    int Ru = R_bound[u];
    int size_L = u - Lu;
    int size_R = Ru - u;

    long long count = 0;

    if (size_L <= size_R) {
        for (int i = Lu; i <= u; i++) {
            int ql = (u > i + 1) ? u : (i + 1);
            long long max_j = (long long)i + K;
            int qr = (max_j < Ru) ? (int)max_j : Ru;

            if (ql <= qr) {
                count += count_range(arrX, N, (i - A[i]) + K, ql, qr);
                count += count_range(arrY, N, (i + A[i]) + K, ql, qr);
                if (max_j <= Ru && max_j >= ql && A[max_j] == A[i]) {
                    count--;
                }
            }
        }
    } else {
        for (int j = u; j <= Ru; j++) {
            int qr = (u < j - 1) ? u : (j - 1);
            long long min_i = (long long)j - K;
            int ql = (min_i > Lu) ? (int)min_i : Lu;

            if (ql <= qr) {
                count += count_range(arrX, N, (j - A[j]) - K, ql, qr);
                count += count_range(arrY, N, (j + A[j]) - K, ql, qr);
                if (min_i >= Lu && min_i <= qr && A[min_i] == A[j]) {
                    count--;
                }
            }
        }
    }

    W[T[u]] += count;
}

int main() {
    struct rlimit rl;
    if (getrlimit(RLIMIT_STACK, &rl) == 0) {
        rl.rlim_cur = 256 * 1024 * 1024;
        setrlimit(RLIMIT_STACK, &rl);
    }

    N = (int)read_ll();
    Q = (int)read_ll();
    K = read_ll();

    for (int i = 1; i <= N; i++) {
        A[i] = read_ll();
        arrX[i - 1].val = i - A[i];
        arrX[i - 1].idx = i;
        arrY[i - 1].val = i + A[i];
        arrY[i - 1].idx = i;
    }

    qsort(arrX, N, sizeof(Point), cmp_point);
    qsort(arrY, N, sizeof(Point), cmp_point);

    for (int t = 1; t <= Q; t++) {
        D[t] = (int)read_ll();
        T[D[t]] = t;
        used[D[t]] = 1;
    }

    int cur_t = Q + 1;
    for (int i = 1; i <= N; i++) {
        if (!used[i]) {
            T[i] = cur_t++;
        }
    }

    int top = 0;
    for (int i = 1; i <= N; i++) {
        int last = 0;
        while (top > 0 && T[stk[top]] > T[i]) {
            last = stk[top--];
        }
        left_child[i] = last;
        if (top > 0) {
            right_child[stk[top]] = i;
        }
        stk[++top] = i;
    }
    int root = stk[1];

    get_bounds(root);
    solve_tree(root);

    long long total = 0;
    for (int t = 1; t <= N; t++) {
        total += W[t];
    }

    ans[0] = total;
    for (int t = 1; t <= Q; t++) {
        ans[t] = ans[t - 1] - W[t];
    }

    for (int t = 0; t <= Q; t++) {
        printf("%lld\n", ans[t]);
    }

    return 0;
}
